function renderCompileChoices(){const texFiles=Object.keys(files).filter(name=>extension(name)==="tex").sort((a,b)=>a===mainFile?-1:b===mainFile?1:a.localeCompare(b));compileChoices.replaceChildren();if(!texFiles.length){const empty=document.createElement("p");empty.className="compile-empty";empty.textContent="Add a .tex file to compile.";compileChoices.append(empty);return}texFiles.forEach(name=>{const choice=document.createElement("button"),icon=document.createElement("span"),label=document.createElement("span"),meta=document.createElement("span");choice.type="button";choice.className=`compile-choice${name===mainFile?" current":""}`;choice.setAttribute("role","menuitem");icon.className="compile-choice-icon";icon.textContent="T";label.className="compile-choice-label";label.textContent=name;meta.className="compile-choice-meta";meta.textContent=name===mainFile?"CURRENT MAIN":name===activeFile?"OPEN":"TEX";choice.append(icon,label,meta);choice.addEventListener("click",async event=>{event.stopPropagation();if(isTextFile(activeFile))files[activeFile]=editor.value;mainFile=name;invalidateHTML();renderFileTree();selectFile(name);closeCompileMenu();await persistProject();notify(`${name} selected for PDF compilation`);compile()});compileChoices.append(choice)})}
