function renderFileTree(filter=""){const tree=document.querySelector(".file-tree");tree.replaceChildren();Object.keys(files).sort((a,b)=>a===mainFile?-1:b===mainFile?1:a.localeCompare(b)).filter(name=>name.toLowerCase().includes(filter.toLowerCase())).forEach(name=>{const button=document.createElement("button"),ext=extension(name),icon=document.createElement("span"),label=document.createElement("span"),meta=document.createElement("i");button.className=`tree-row${name===activeFile?" active":""}`;button.dataset.file=name;button.setAttribute("role","treeitem");icon.className=ext==="bib"?"bib-icon":imageExtensions.has(ext)||ext==="pdf"?"image-icon":"tex-icon";icon.textContent=ext==="bib"?"B":imageExtensions.has(ext)||ext==="pdf"?"▧":"T";label.textContent=name;meta.className=name===mainFile?"main-badge":"file-size";meta.textContent=name===mainFile?"MAIN":formatBytes(assetSize(files[name]));button.append(icon,label,meta);button.addEventListener("click",()=>selectFile(name));tree.append(button)})}
function selectFile(name,initial=false){
  if(!(name in files))return;
  if(!initial&&isTextFile(activeFile))files[activeFile]=editor.value;
  activeFile=name;
  const textFile=isTextFile(name),value=files[name],ext=extension(name);
  editor.value=textFile?String(value):`[Project asset]\n\n${name}\n${formatBytes(assetSize(value))}\n\nBinary assets are transferred directly to pdfTeX when you compile.`;
  editor.readOnly=!textFile;
  if(assetPreviewURL){URL.revokeObjectURL(assetPreviewURL);assetPreviewURL=null}
  editor.style.backgroundImage="none";
  if(imageExtensions.has(ext)&&value instanceof Uint8Array){assetPreviewURL=URL.createObjectURL(new Blob([value],{type:ext==="png"?"image/png":"image/jpeg"}));editor.style.backgroundImage=`linear-gradient(#111b29cc,#111b29cc),url("${assetPreviewURL}")`;editor.style.backgroundRepeat="no-repeat";editor.style.backgroundPosition="center";editor.style.backgroundSize="cover,contain"}
  document.querySelector("#activeFileName").textContent=name;
  const setMain=document.querySelector("#setMainBtn");setMain.hidden=ext!=="tex";setMain.disabled=name===mainFile;setMain.textContent=name===mainFile?"Main file":"Use as main";
  document.querySelectorAll(".tree-row").forEach(b=>b.classList.toggle("active",b.dataset.file===name));updateLines();cursor();document.querySelector(".file-panel").classList.remove("open")
}
