compressionDialog.addEventListener("click",event=>{if(event.target===compressionDialog)compressionDialog.close()});
runCompression.addEventListener("click",async()=>{
  if(!latexEngine.isReady()){notify("The browser compiler is still loading");return}
  if(activeFile!==mainFile)selectFile(mainFile);
  const source=editor.value;
  files[mainFile]=source;
  resetCompressionResults();runCompression.disabled=true;compileBtn.disabled=true;runCompression.classList.add("running");runCompression.innerHTML="<span>↻</span> Building uncompressed baseline…";
  const baseline=await compileSource(compressionVariant(source,false),mainFile);
  document.querySelector("#baselineTime").textContent=`${baseline.seconds.toFixed(1)} s build`;
  if(baseline.status!==0||!baseline.pdf){document.querySelector("#baselineBytes").textContent="Failed";document.querySelector("#artifactStatus").textContent="Test stopped";document.querySelector("#rawLog").textContent=`=== BASELINE ===\n${baseline.log||"No compiler log was returned."}`;runCompression.innerHTML="<span>↻</span> Run baseline + optimized builds";runCompression.classList.remove("running");runCompression.disabled=false;compileBtn.disabled=false;compressionDialog.close();showView("log");notify("Baseline build failed — see compiler log");return}
  document.querySelector("#baselineBytes").textContent=formatBytes(baseline.pdf.byteLength);runCompression.innerHTML="<span>↻</span> Building lossless optimized PDF…";
  const optimized=await compileSource(compressionVariant(source,true),mainFile);
  document.querySelector("#optimizedTime").textContent=`${optimized.seconds.toFixed(1)} s build`;document.querySelector("#rawLog").textContent=`=== BASELINE (compression 0 / object streams 0) ===\n${baseline.log||"No compiler log was returned."}\n\n=== OPTIMIZED (compression 9 / object streams 3) ===\n${optimized.log||"No compiler log was returned."}`;
  if(optimized.status!==0||!optimized.pdf){document.querySelector("#optimizedBytes").textContent="Failed";document.querySelector("#artifactStatus").textContent="Test incomplete";compressionDialog.close();showView("log");notify("Optimized build failed — see compiler log")}else{optimizedPDF=optimized.pdf;if(optimizedURL)URL.revokeObjectURL(optimizedURL);optimizedURL=URL.createObjectURL(new Blob([optimizedPDF],{type:"application/pdf"}));const baselineSize=baseline.pdf.byteLength,optimizedSize=optimized.pdf.byteLength,saved=Math.max(0,baselineSize-optimizedSize),percentage=baselineSize?saved/baselineSize*100:0;document.querySelector("#optimizedBytes").textContent=formatBytes(optimizedSize);document.querySelector("#compressionSavings").textContent=`${percentage.toFixed(1)}%`;document.querySelector("#savedBytes").textContent=`${formatBytes(saved)} saved`;document.querySelector("#artifactStatus").textContent="None introduced";downloadOptimized.disabled=false;notify("Compression experiment complete")}
  runCompression.innerHTML="<span>↻</span> Run baseline + optimized builds";runCompression.classList.remove("running");runCompression.disabled=false;compileBtn.disabled=false
});
downloadOptimized.addEventListener("click",()=>{if(!optimizedURL){notify("Run the compression experiment first");return}const link=document.createElement("a");link.href=optimizedURL;link.download="main-optimized.pdf";link.click()});
