async function initializeCompiler(){try{document.querySelector("#healthText").textContent="Loading local pdfTeX…";await Promise.all([latexEngine.loadEngine(),ensureFormatFile()]);compileBtn.disabled=false;compileBtn.innerHTML='<span aria-hidden="true">▶</span> Compile PDF <kbd>Ctrl ↵</kbd>';document.querySelector("#healthText").textContent="Offline-ready compiler";notify("Local pdfTeX and format file are ready") }catch(error){compileBtn.disabled=true;compileBtn.textContent="Compiler unavailable";document.querySelector("#healthText").textContent="Compiler failed to load";document.querySelector("#healthText").style.color="#d85146";document.querySelector("#rawLog").textContent=String(error);document.querySelector("#logTitle").textContent="The local WebAssembly compiler did not load.";document.querySelector("#logExplanation").textContent="Refresh once. If the problem continues, check that WebAssembly and web workers are allowed in this browser."}}
restoreProject().finally(()=>{updateLines();cursor();if(isTextFile(activeFile))render(editor.value);initializeCompiler().then(()=>{if(latexEngine.isReady()){runCompression.disabled=false;runCompression.innerHTML='<span>↻</span> Run baseline + optimized builds'}else{runCompression.disabled=true;runCompression.textContent="Compiler unavailable"}})});
